const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,d=0)=>n==null?'Unavailable':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:d,minimumFractionDigits:d}).format(Number(n));
const compact=n=>n>=10000000?'₹'+(n/10000000).toFixed(2)+' Cr':n>=100000?'₹'+(n/100000).toFixed(2)+'L':money(n);
const number=n=>Number(n).toLocaleString('en-IN',{maximumFractionDigits:4});
const pct=n=>n==null?'Unavailable':(n*100).toFixed(2)+'%';
const date=d=>d?new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not available';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',holdings:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12h18M10 12v3h4v-3"/>',sips:'<path d="M20 7a8 8 0 0 0-14-2L3 8m0-5v5h5M4 17a8 8 0 0 0 14 2l3-3m0 5v-5h-5"/>',goals:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',funds:'<path d="M3 19V5m0 14h18M7 14l4-4 4 2 5-7"/><path d="M16 5h4v4"/>',reports:'<path d="M6 3h9l4 4v14H5V3zM14 3v5h5M8 12h8m-8 4h6"/>',imports:'<path d="M12 16V3m-4 4 4-4 4 4M4 14v6h16v-6"/>',health:'<path d="M3 12h4l3-7 4 14 3-7h4"/>',settings:'<path d="m10 3-1 3-3 1-3 3 3 2v3l3 2 1 4h4l1-4 3-2v-3l3-2-3-3-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',down:'<path d="M12 3v13m-4-4 4 4 4-4M4 17v4h16v-4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',arrow:'<path d="M4 16 11 9l4 4 6-10M15 3h6v6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>'})[name]||'<path d="M5 12h14m-6-6 6 6-6 6"/>'}</svg>`;
const navItems=[['overview','Overview'],['holdings','My holdings'],['sips','SIPs & calendar'],['goals','Goals & planning'],['funds','Fund explorer'],['reports','Weekly reports'],['imports','Import center'],['health','Data health'],['settings','Settings']];
let space=localStorage.getItem('artha-space')||'demo',page=location.hash.slice(1)||'overview',data=null,period='ALL',preview=null,csvFile=null,planner=null;
const toast=(message,error=false)=>{const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.className='',5000);};
async function request(path,body){const response=await fetch('/api'+path+(path.includes('?')?'&':'?')+'space='+space,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await response.json();if(!response.ok)throw new Error(d.error||'Request failed');return d;}
async function load(){try{data=await request('/state');render();}catch(e){$('#content').innerHTML=`<div class="empty-state"><h1>Your private investment space</h1><p>${esc(e.message)}</p><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in with ChatGPT</a></div>`;}}
function heading(title,sub,actions='',eyebrow='YOUR WEALTH, WITH PURPOSE'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
const btn=(text,action,extra='',style='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`;
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;$('#modal').showModal();}
function close(){$('#modal').close();}
const sipTotal=()=>data.sips.filter(s=>s.status==='planned').reduce((sum,s)=>sum+Number(s.amount)/(s.cadence==='quarterly'?3:1),0);
function render(){
 if(!navItems.some(x=>x[0]===page)&&page!=='methodology')page='overview';
 $('#nav').innerHTML=navItems.map(([key,label],i)=>`${i===5?'<div class="nav-section">STAY IN THE KNOW</div>':''}<button class="${page===key?'active':''}" data-action="navigate" data-page="${key}">${icon(key)}<span>${label}</span>${key==='reports'&&data.reports.length?`<span class="nav-badge">${data.reports.length}</span>`:''}</button>`).join('');
 $('#crumb').textContent=navItems.find(x=>x[0]===page)?.[1]||'Methodology';$('#space-label').textContent=space==='demo'?'Demo workspace':'Personal workspace';
 $('#workspace-banner').innerHTML=space==='demo'?`<div class="demo-banner"><span>✧ &nbsp; You’re exploring with synthetic data. Every name and value is illustrative.</span><button data-action="switch">Start my portfolio ↗</button></div>`:`<div class="demo-banner personal-banner"><span>◉ &nbsp; Your personal workspace · private records · end-of-day valuations</span><button data-action="switch">Explore demo ↗</button></div>`;
 $('#content').innerHTML=({overview,holdings,sips,goals,funds,reports,imports,health,settings,methodology})[page]();
 if(page==='goals')calculatePlanner();
}
function metric(label,value,note,featured=false,ic='info'){return `<div class="metric ${featured?'featured':''}"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;}
function overview(){const p=data.portfolio,gain=Number(p.gain),basis=Number(p.basis);return heading('A little clarity. A lot of possibility.','Your investments, goals, and next steps. All in one place.',btn(icon('plus')+' Add investment','add-investment','','primary')+btn(icon('down')+' Export','export'), 'THE BIG PICTURE')+
 (space==='personal'&&!p.holdings.length?`<div class="onboard"><h2>Let’s give your money a direction.</h2><p>Import your investments, set your budget, and start with a goal.</p>${btn('Import a portfolio →','navigate','data-page="imports"','primary')} ${btn('Set up my profile','profile')}</div>`:'')+
 `<div class="metrics">${metric('Total portfolio value',money(p.total),p.complete?'As of '+date(p.valuationCutoff):'Partial · '+p.unpriced+' unpriced positions',true,'holdings')}${metric('Known invested cost',p.basis===null?'Unavailable':money(p.basis),'Remaining acquisition cost · FIFO',false,'down')}${metric('Unrealized gain',p.gain===null?'Unavailable':money(p.gain),p.gain===null?'Acquisition history or valuations missing':`<span class="badge">${basis?((gain/basis)*100).toFixed(2)+'%':'—'}</span> <span>on known remaining cost</span>`,false,'arrow')}${metric('Monthly planned SIP',money(sipTotal()),data.sips.filter(s=>s.status==='planned').length+' active plans · '+money(data.preferences.budget||0)+' budget',false,'sips')}</div>
 <div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>Your wealth, over time</h2><div class="panel-subtitle">Small steps. A bigger picture.</div></div><div class="periods">${['6M','1Y','ALL'].map(x=>`<button class="${period===x?'active':''}" data-action="period" data-period="${x}">${x==='ALL'?'All time':x}</button>`).join('')}</div></div><div class="chart-meta"><span>${p.xirr.value===null?'Personal XIRR unavailable':pct(p.xirr.value)+' personal XIRR'} ${icon('info','inline-icon')}</span><div class="legend"><span><i></i>Portfolio value</span><span><i class="line"></i>Net contributions</span></div></div>${wealthChart()}<div class="chart-foot"><span>◷ &nbsp; Valuations through ${date(p.valuationCutoff)} · ${p.coverage==null?'—':Math.round(p.coverage*100)+'%'} of priced value fresh</span><details><summary>View chart data</summary>${chartTable()}</details></div></section><section class="panel table-panel"><div class="panel-head"><h2>A look at your holdings <span class="badge gray">${p.holdings.length}</span></h2><button class="text-btn" data-action="navigate" data-page="holdings">All holdings ↗</button></div>${holdingsTable(p.holdings.slice(0,5),false)}<div class="table-foot"><span>Latest dated prices · no intraday quotes</span><button data-action="navigate" data-page="health">Check data health →</button></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>Where your money lives</h2>${icon('info','inline-icon')}</div>${allocationView()}<div class="insight-strip">${icon('info','inline-icon')}<span>${p.holdings.length?'Allocation reflects imported classifications. Unclassified assets need review.':'Add holdings to see your allocation.'}</span></div></section><section class="panel"><div class="panel-head"><h2>Made for your milestones</h2><button class="text-btn" data-action="navigate" data-page="goals">View all ↗</button></div><div class="goals-list">${data.goals.slice(0,3).map(goalMini).join('')||'<div class="empty-state"><p>Your next chapter starts with a goal.</p></div>'}</div><div class="panel-bottom"><button class="text-btn" data-action="new-goal">+ &nbsp; Plan a new goal</button></div></section><section class="panel"><div class="panel-head"><h2>Next on your calendar</h2>${icon('calendar','inline-icon')}</div>${nextSip()}</section></div></div>`;}
function filteredHistory(){let h=data.history.filter(x=>x.value!==null);if(period!=='ALL'){const d=new Date();d.setMonth(d.getMonth()-(period==='6M'?6:12));h=h.filter(x=>Date.parse(x.date)>=d.getTime());}return h;}
function wealthChart(){const h=filteredHistory();if(h.length<2)return '<div class="empty-state" style="height:230px"><p>Import dated valuations to start your portfolio history.</p></div>';return lineChart(h.map(x=>x.date),[h.map(x=>x.value),h.map(x=>x.contributions)],['#648257','#bdc8b2'],true);}
function lineChart(labels,series,colors,area=false){const width=700,height=215,pad={left:54,right:15,top:20,bottom:33};const vals=series.flat().filter(Number.isFinite),max=Math.max(...vals,1)*1.12,min=Math.min(0,...vals);const y=v=>height-pad.bottom-(v-min)/(max-min)*(height-pad.bottom-pad.top);const x=i=>pad.left+i/Math.max(1,labels.length-1)*(width-pad.left-pad.right);let out=`<div class="chart-wrap"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Investment growth chart. Exact values are available in the chart data table."><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#c8d9a5" stop-opacity=".45"/><stop offset="100%" stop-color="#edf3e3" stop-opacity=".15"/></linearGradient></defs>`;
 for(let i=0;i<4;i++){const v=min+(max-min)*i/3;out+=`<path d="M${pad.left} ${y(v)}H${width-pad.right}" stroke="#edf0e6" stroke-dasharray="3 4"/><text x="${pad.left-10}" y="${y(v)+3}" text-anchor="end" class="chart-label">${esc(compact(v))}</text>`;}
 series.forEach((points,j)=>{const coords=points.map((v,i)=>`${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');if(j===0&&area)out+=`<polygon points="${x(0)},${y(0)} ${coords} ${x(points.length-1)},${y(0)}" fill="url(#areaGradient)"/>`;out+=`<polyline points="${coords}" fill="none" stroke="${colors[j]}" stroke-width="${j===0?2.5:1.6}" ${area&&j===1?'stroke-dasharray="5 5"':''}/>`;out+=`<circle cx="${x(points.length-1)}" cy="${y(points.at(-1))}" r="3.5" fill="${colors[j]}" stroke="white" stroke-width="2"/>`;});
 [...new Set([0,Math.floor((labels.length-1)/3),Math.floor(2*(labels.length-1)/3),labels.length-1])].forEach(i=>{out+=`<text x="${x(i)}" y="${height-10}" text-anchor="middle" class="chart-label">${esc(/^\d{4}-/.test(labels[i])?new Date(labels[i]).toLocaleDateString('en-IN',{month:'short',year:'2-digit'}):labels[i])}</text>`;});return out+'</svg></div>';}
function chartTable(){return `<table><thead><tr><th>Date</th><th>Value</th><th>Net contributions</th></tr></thead><tbody>${filteredHistory().map(x=>`<tr><td>${date(x.date)}</td><td>${money(x.value)}</td><td>${money(x.contributions)}</td></tr>`).join('')}</tbody></table>`;}
function allocationView(){const a=Object.entries(data.portfolio.allocation).filter(x=>x[1]>0),total=Number(data.portfolio.total),colors=['#657e4d','#a9b78b','#d9cd9c','#e2e6d5'];let cursor=0;const gradient=a.map(([k,v],i)=>{const start=cursor;cursor+=v/Math.max(1,total)*100;return `${colors[i%4]} ${start}% ${cursor}%`;}).join(',');return `<div class="allocation-body"><div class="donut" style="background:${a.length?'conic-gradient('+gradient+')':'#eff3e7'}"><div class="donut-center"><strong>${a.length}</strong><span>asset classes</span></div></div></div><div class="allocation-legend">${a.map(([k,v],i)=>`<div><i style="background:${colors[i%4]}"></i>${esc(k)}<b>${(v/total*100).toFixed(1)}%</b></div>`).join('')}</div>`;}
const goalIcon=g=>({home:'⌂',sun:'☀',plane:'↗'})[g.icon]||'◎';
function goalMini(g){const progress=Math.min(100,(g.corpus||0)/Math.max(1,g.target)*100);return `<div class="goal-card"><div class="goal-title"><span class="goal-emoji">${goalIcon(g)}</span><span>${esc(g.name)}</span><button class="text-btn" data-action="edit-goal" data-id="${esc(g.id)}" aria-label="Edit ${esc(g.name)}">↗</button></div><div class="goal-number"><strong>${compact(g.corpus||0)} <span class="muted">of ${compact(g.target)}</span></strong><span>${progress.toFixed(0)}%</span></div><div class="progress"><i style="width:${progress}%"></i></div><div class="goal-foot"><span>${g.years} years to go</span><span>${money(g.monthly)}/mo</span></div></div>`;}
function nextSip(){const s=data.sips.filter(s=>s.status==='planned').sort((a,b)=>a.day-b.day),todayDay=+today().slice(-2),sip=s.find(s=>s.day>=todayDay)||s[0];if(!sip)return '<div class="next-sip"><p>No upcoming plans yet.</p></div>';const month=new Date();if(sip.day<todayDay)month.setMonth(month.getMonth()+1);return `<div class="next-sip"><div class="calendar-icon">${month.toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}<strong>${sip.day}</strong></div><div><b>${esc(sip.name.split(' ').slice(0,3).join(' '))}</b><p>Planned contribution</p></div><strong>${money(sip.amount)}</strong></div>`;}
function holdingsTable(rows,full=true){if(!rows.length)return `<div class="empty-state">${icon('holdings')}<h3>A home for your investments</h3><p>Add a holding or import a CSV to bring your portfolio together.</p>${btn('Add investment','add-investment','','primary')}</div>`;return `<div class="table-scroll"><table><thead><tr><th>Investment</th>${full?'<th>Account</th><th class="num">Units</th><th class="num">NAV / price</th>':''}<th class="num">Current value</th><th class="num">Unrealized gain</th>${full?'<th class="num">Weight</th><th>Data status</th>':'<th class="num">Weight</th>'}</tr></thead><tbody>${rows.map((h,i)=>`<tr><td><div class="holding-cell"><span class="fund-icon b${i%4}">${esc(h.type==='MF'?h.name.split(' ').map(x=>x[0]).slice(0,2).join(''):h.type==='ETF'?'Au':h.name.slice(0,2).toUpperCase())}</span><div><button class="fund-name" data-action="holding" data-id="${esc(h.id)}">${esc(h.name)}</button><div class="fund-sub">${esc(h.category)}${h.plan?' · '+esc(h.plan)+' '+esc(h.option):''}</div></div></div></td>${full?`<td>${esc(h.account)}</td><td class="num">${number(h.units)}</td><td class="num">${h.quote?money(h.quote.price,2):'Unavailable'}<div class="fund-sub">${date(h.quote?.date)}</div></td>`:''}<td class="num">${money(h.value)}</td><td class="num ${Number(h.unrealized)>=0?'positive':'negative'}">${money(h.unrealized)}${h.unrealized!==null&&h.basis&&Number(h.basis)>0?`<div class="fund-sub positive">${(Number(h.unrealized)/Number(h.basis)*100).toFixed(2)}%</div>`:''}</td><td class="num">${h.value===null?'Unavailable':data.portfolio.total>0?(Number(h.value)/Number(data.portfolio.total)*100).toFixed(1)+'%':'—'}</td>${full?`<td><span class="badge ${h.stale?'amber':'gray'}">${!h.quote?'Unpriced':h.stale?'Dated / review':'Dated price'}</span></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function holdings(){return heading('Your portfolio, in focus.','Every investment. Every account. One considered view.',btn(icon('plus')+' Add investment','add-investment','','primary')+btn('Import CSV','navigate','data-page="imports"'))+`<section class="panel"><div class="panel-head"><h2>All holdings <span class="badge gray">${data.portfolio.holdings.length}</span></h2><span class="muted">As of ${date(data.portfolio.asOf)}</span></div><div class="search-row"><input id="holding-search" aria-label="Search holdings" placeholder="Search investments or account…"><select id="holding-type" aria-label="Filter by type"><option value="">All asset types</option value="MF">Mutual funds</option value="STOCK">Stocks</option value="ETF">ETFs</option></select><select id="holding-view" aria-label="Account view"><option value="account">By account</option><option value="consolidated">Consolidated</option></select></div><div id="holding-rows">${holdingsTable(data.portfolio.holdings)}</div></section><div class="callout section-space" style="margin-top:18px">${icon('info','inline-icon')} &nbsp; ${data.portfolio.unpriced} unpriced holdings · Latest transaction import: ${data.portfolio.lastImport?date(data.portfolio.lastImport.slice(0,10)):'none'} · Imported investments reflect the records you provide.</div>`;}
function sips(){const total=sipTotal(),budget=Number(data.preferences.budget||0);return heading('Consistency is a superpower.','Plan your contributions. Keep the bigger picture in sight.',btn(icon('plus')+' New SIP plan','new-sip','','primary'))+`<div class="metrics">${metric('Monthly commitment',money(total),'Monthly equivalent of active plans',true,'sips')}${metric('Investable budget',money(budget),'Set in your financial profile',false,'holdings')}${metric('Budget headroom',money(budget-total),budget<total?'Review contribution budget':'Available for future goals',false,'arrow')}${metric('Active SIP plans',data.sips.filter(s=>s.status==='planned').length,'Manual schedules · no bank mandates',false,'calendar')}</div><section class="panel"><div class="panel-head"><h2>Your contribution calendar</h2><span class="badge gray">Planning only</span></div>${data.sips.length?`<div class="table-scroll"><table><thead><tr><th>Investment</th><th>Cadence</th><th>Planned day</th><th class="num">Amount</th><th>Schedule</th><th>Imported evidence</th><th></th></tr></thead><tbody>${data.sips.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.cadence||'monthly')}</td><td>${s.day} of month</td><td class="num">${money(s.amount)}</td><td><span class="badge ${s.status==='paused'?'amber':'gray'}">${esc(s.status)}</span></td><td><span class="muted">${sipEvidence(s)}</span></td><td><button class="text-btn" data-action="edit-sip" data-id="${esc(s.id)}">Edit →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><h3>Start a steady habit</h3><p>Create a manual SIP schedule to track planned contributions.</p></div>'}</section><div class="callout amber" style="margin-top:20px">A missing transaction means “not found in imported transactions.” Import dates and allotment dates may differ. Plans never create bank mandates or execute investments.</div>`;}
function sipEvidence(s){if(s.status!=='planned')return '—';const prefix=today().slice(0,7);const candidates=data.events.filter(e=>e.date.startsWith(prefix)&&e.type==='BUY'&&e.name===s.name&&Math.abs(Number(e.amount)-Number(s.amount))<.01&&Math.abs(+e.date.slice(-2)-Number(s.day))<=5);return candidates.length===1?'Matching transaction found':candidates.length>1?'Ambiguous matches · review':s.day<+today().slice(-2)?'Not found in imported transactions':'Planned · awaiting import';}
function goals(){const p=planner||{name:'My next milestone',target:2500000,years:10,corpus:0,monthly:10000,inflation:6,stepUp:10,timing:'end',todayMoney:true};return heading('Give your money a destination.','Explore the tradeoffs between time, contributions, and your goal.',btn(icon('plus')+' New goal','new-goal','','primary'))+`<div class="mini-grid section-space">${data.goals.map(g=>`<section class="panel goal-tile">${goalMini(g)}<div class="tooltip-note">${g.todayMoney?'Target in today’s money · inflation applies':'Future nominal target · no additional inflation'}</div><button class="text-btn" style="margin-top:14px" data-action="edit-goal" data-id="${esc(g.id)}">Explore plan →</button></section>`).join('')}</div><div class="full-grid"><section class="panel"><div class="panel-head"><div><h2>Your SIP planning studio</h2><div class="panel-subtitle">A practical plan for something meaningful.</div></div><span class="badge gray">Illustration</span></div><div class="body-pad"><form id="planner-form"><input type="hidden" name="id" value="${esc(p.id||'')}"><div class="form-grid">${field('Goal name','name',p.name,'text','wide')}${field('Target amount (₹)','target',p.target,'number')}${field('Years to goal','years',p.years,'number')}${field('Existing planning corpus (₹)','corpus',p.corpus,'number')}${field('Monthly contribution (₹)','monthly',p.monthly,'number')}${field('Annual step-up (%)','stepUp',p.stepUp,'number')}${field('Inflation assumption (%)','inflation',p.inflation,'number')}<label class="field">Contribution timing<select name="timing"><option value="end" ${p.timing==='end'?'selected':''}>Month end</option><option value="begin" ${p.timing==='begin'?'selected':''}>Month beginning</option></select></label><label class="field">Target amount basis<select name="todayMoney"><option value="true" ${p.todayMoney?'selected':''}>Today’s money</option><option value="false" ${!p.todayMoney?'selected':''}>Future amount</option></select></label>${field('Conservative return (%)','rate0',p.rates?.[0]??6,'number')}${field('Base return (%)','rate1',p.rates?.[1]??10,'number')}${field('Optimistic return (%)','rate2',p.rates?.[2]??12,'number')}</div><p class="tooltip-note">Return assumptions are editable illustrations. The first annual increase follows 12 completed contributions. Planning corpus is an input, not a verified brokerage holding.</p><div class="form-actions">${btn('Recalculate','calculate')}${btn('Save goal & plan','save-goal','','primary')}</div></form></div></section><section class="panel"><div class="panel-head"><div><h2>One goal. Three possible paths.</h2><div class="panel-subtitle">Scenarios, not promised outcomes.</div></div></div><div class="body-pad" id="planner-result"><div class="loading">Calculating…</div></div></section></div>`;}
function field(label,name,value,type='text',cls='',extra=''){return `<label class="field ${cls}">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${type==='number'?'step="any" min="0"':''} ${extra}></label>`;}
let calcTicket=0;
function plannerValues(){const b=Object.fromEntries(new FormData($('#planner-form')));for(const k of ['target','years','corpus','monthly','inflation','stepUp'])b[k]=Number(b[k]);b.rates=[+b.rate0,+b.rate1,+b.rate2];b.todayMoney=b.todayMoney==='true';b.assignments=planner?.assignments||[];b.icon=planner?.icon||'sun';if(!b.id)delete b.id;return b;}
async function calculatePlanner(){if(!$('#planner-form'))return;const ticket=++calcTicket;try{const v=plannerValues(),r=await request('/simulate',v);if(ticket!==calcTicket)return;$('#planner-result').innerHTML=`<div class="eyebrow">FUTURE NOMINAL TARGET</div><div class="big-stat">${money(r.target)}</div><div class="muted">${r.months} monthly contributions · ${v.todayMoney?'inflation adjusted':'target already in future money'}</div>${lineChart(r.scenarios[1].points.map(x=>'Year '+Math.round(x.month/12)),r.scenarios.map(s=>s.points.map(p=>p.value)),['#b8c7a2','#4f7540','#d4bb75'])}<div class="planner-results">${r.scenarios.map((s,i)=>`<div class="scenario ${i===1?'base':''}"><div><span>${s.name} · ${s.rate}%</span><b>${compact(s.corpus)}</b></div><small>Starting SIP needed: <strong>${money(s.required)}</strong><br>Contributions: ${compact(s.contributions)}<br>${s.shortfall?'Gap: '+compact(s.shortfall):'Target covered in this scenario'}</small></div>`).join('')}</div><div class="callout ${r.scenarios[1].shortfall?'amber':''}" style="margin-top:18px">${r.scenarios[1].shortfall?'The base case has a funding gap. Explore a higher contribution, a later date, or a smaller target.':'The target is covered under the base assumptions. Review the conservative case before deciding.'} ${data.preferences.budget&&r.scenarios[1].required>data.preferences.budget?'The required starting SIP exceeds your saved monthly budget.':''}</div><details style="margin-top:18px"><summary class="text-btn">View projection data</summary><div class="table-scroll"><table><thead><tr><th>Year</th><th>Conservative</th><th>Base</th><th>Optimistic</th></tr></thead><tbody>${r.scenarios[0].points.map((p,i)=>`<tr><td>${p.month/12}</td>${r.scenarios.map(s=>`<td>${money(s.points[i].value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}catch(e){if($('#planner-result'))$('#planner-result').innerHTML=`<div class="callout amber">${esc(e.message)}</div>`;}}
function funds(){const funds=data.portfolio.holdings.filter(h=>h.type==='MF'||h.type==='ETF');return heading('Research with perspective.','Historical standing, personal fit, and data confidence deserve separate answers.')+`<div class="callout amber section-space">Fund discovery needs dated benchmark, category, cost, and disclosure coverage. No live research provider is configured. Existing investments are shown below without fabricated ranks or recommendations.</div><div class="mini-grid">${funds.map(h=>`<section class="panel body-pad"><span class="badge gray">${h.type==='ETF'||/index/i.test(h.category)?'Passive evaluation':'Category review'}</span><h2 style="margin:17px 0 8px">${esc(h.name)}</h2><div class="muted">${esc(h.plan)} ${esc(h.option)} · ${esc(h.category)}</div><div class="divider"></div><div class="stat-row"><span>Historical standing</span><b>Insufficient data</b></div><div class="stat-row"><span>Personal suitability</span><b>${data.preferences.profile?'Needs goal & liquidity review':'Profile incomplete'}</b></div><div class="stat-row"><span>Data confidence</span><b>Price only · no peer coverage</b></div><div class="form-actions">${btn('Review investment →','holding',`data-id="${esc(h.id)}"`)}</div></section>`).join('')||'<section class="panel empty-state"><h3>No imported funds yet</h3><p>Add investments to begin a factual review.</p></section>'}</div>`;}
function reports(){return heading('A moment to take stock.','Frozen weekly snapshots. Less noise, more perspective.',btn('Generate a report','generate-report','','primary'))+`<div class="callout section-space">${icon('calendar','inline-icon')} &nbsp; Preferred schedule: ${esc(data.preferences.reportDay||'Saturday')} at ${esc(data.preferences.reportTime||'09:00')} Asia/Kolkata. Background worker: <b>${esc(data.scheduler)}</b>. Generate an in-app report any time.</div><section class="panel"><div class="panel-head"><h2>Your weekly reading</h2><span class="badge gray">${data.reports.length} reports</span></div>${data.reports.length?[...data.reports].sort((a,b)=>b.period.localeCompare(a.period)).map(r=>`<article class="report-card"><div class="report-icon">${icon('reports')}</div><div><h3>Portfolio review · ${date(r.period)}</h3><p>${date(r.start)} – ${date(r.period)} · Revision ${r.revision} · Calculation v${r.calculationVersion}</p></div><span class="badge ${r.status==='Partial'?'amber':'gray'}">${esc(r.status)}</span>${btn('Read report →','read-report',`data-id="${esc(r.id)}"`)}</article>`).join(''):'<div class="empty-state">'+icon('reports')+'<h3>A clearer week starts here.</h3><p>Generate your first snapshot. Reports preserve their original figures and data gaps.</p>'+btn('Create weekly report','generate-report','','primary')+'</div>'}</section>`;}
function imports(){return heading('Bring your investments together.','Manual entries and transparent CSV imports. You review every batch.',btn('Download template','template'))+`<div class="full-grid"><section class="panel"><div class="panel-head"><h2>Import transactions or opening holdings</h2></div><div class="body-pad"><div class="import-steps"><span>1 Upload</span> → <span>2 Map fields</span> → <span>3 Review</span> → <span>4 Confirm</span></div><label class="import-drop">${icon('imports')}<b>Choose a CSV to get started</b><p>UTF-8 CSV · up to 2 MB / 10,000 rows</p><input id="csv-file" type="file" accept=".csv,text/csv" aria-label="Choose CSV file"></label><div id="mapping-area"></div><p class="tooltip-note">Statement PDFs, CAS, broker APIs, and password-protected documents require separate, verified parsers. Only the documented generic CSV format is supported here.</p></div></section><section class="panel"><div class="panel-head"><h2>Start with what you know</h2></div><div class="body-pad"><p class="muted">Have only a statement balance? Add an opening holding. Its value will appear, while personal XIRR and tax basis stay unavailable.</p>${btn(icon('plus')+' Add a manual investment','add-investment','','primary')}<div class="divider"></div><h3>A few things we look out for</h3><div class="stat-row"><span>Instrument identity</span><b>Identifier + type + plan + option</b></div><div class="stat-row"><span>Duplicate handling</span><b>File hash & source references</b></div><div class="stat-row"><span>Identical transactions</span><b>Explicit review</b></div><div class="stat-row"><span>Closing unit differences</span><b>Block posting</b></div><div class="stat-row"><span>Original uploaded file</span><b>Not retained</b></div></div></section></div><section class="panel table-panel"><div class="panel-head"><h2>Import history</h2></div>${data.imports.length?`<div class="table-scroll"><table><thead><tr><th>Batch</th><th>Created</th><th>Status</th><th class="num">Rows</th><th></th></tr></thead><tbody>${[...data.imports].reverse().map(b=>`<tr><td>${esc(b.name)}</td><td>${date(b.createdAt.slice(0,10))}</td><td><span class="badge ${b.status==='previewed'?'amber':'gray'}">${esc(b.status)}</span></td><td class="num">${b.rows.length}</td><td><button class="text-btn" data-action="batch" data-id="${esc(b.id)}">${b.status==='previewed'?'Review →':b.status==='posted'?'View / reverse →':'View →'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><p>Your reviewed imports will appear here.</p></div>'}</section>`;}
function health(){const p=data.portfolio;return heading('Confidence starts with good data.','Know what is current, what is missing, and what needs a second look.',btn('Update a valuation','price'))+`<div class="metrics">${metric('Priced holdings',p.holdings.length-p.unpriced+' / '+p.holdings.length,'Missing prices remain unavailable',true,'holdings')}${metric('Fresh priced value',p.coverage===null?'—':(p.coverage*100).toFixed(1)+'%','Dated-price age check · review holidays',false,'health')}${metric('Stale / unpriced',p.dataQuality.stale,'Older than four calendar days',false,'info')}${metric('Unreconciled events',p.holdings.reduce((s,h)=>s+h.issues.length,0),'Affected conclusions are suppressed',false,'reports')}</div><div class="full-grid"><section class="panel"><div class="panel-head"><h2>Data connections</h2></div><div class="body-pad">${Object.entries(data.providers).map(([k,v])=>`<div class="health-card"><div><h3>${esc({nav:'Mutual fund NAV',stocks:'Stocks & ETFs',benchmarks:'Benchmarks & fund disclosures',tax:'Tax estimates',ai:'AI explanations',email:'Report email'}[k])}</h3><p>${esc(v)}</p></div><span class="badge ${v==='Configured'?'':'gray'}">${v==='Configured'?'Configured':'Setup required'}</span></div>`).join('')}<p class="tooltip-note">AMFI access is disabled until permitted use is acknowledged in server configuration. Exchange data and metadata need suitable sources and licences. Imported prices remain supported.</p>${btn('Refresh configured NAVs','refresh-nav')}</div></section><section class="panel"><div class="panel-head"><h2>Valuation details</h2></div>${holdingsHealth()}<div class="body-pad tooltip-note">Price freshness does not verify units. Source timestamps and latest transaction imports are separate. The current freshness check uses four calendar days; it does not claim an exchange-holiday calendar.</div></section></div>`;}
function holdingsHealth(){return `<div class="table-scroll"><table><thead><tr><th>Investment</th><th>Source / date</th></tr></thead><tbody>${data.portfolio.holdings.map(h=>`<tr><td>${esc(h.name)}<div class="fund-sub">${h.basis===null?'Cost basis unknown':'Known cost basis'}</div></td><td>${date(h.quote?.date)}<div class="fund-sub">${esc(h.quote?.source||'No valuation')}</div></td></tr>`).join('')}</tbody></table></div>`;}
function settings(){const p=data.preferences;return heading('Make this space yours.','Your budget, risk inputs, preferences, and private records.')+`<div class="full-grid"><section class="panel"><div class="panel-head"><h2>Your investing profile</h2>${btn('Review profile','profile','','small-btn')}</div><div class="body-pad"><div class="stat-row"><span>Monthly investable budget</span><b>${money(p.budget||0)}</b></div><div class="stat-row"><span>Risk questionnaire</span><b>${p.profile?'Completed · review inputs':'Not completed'}</b></div><div class="stat-row"><span>Currency / timezone</span><b>INR · Asia/Kolkata</b></div><div class="stat-row"><span>AI explanations</span><b>Off</b></div><p class="tooltip-note">A questionnaire captures inputs; it does not verify your financial circumstances. Personalized fund suitability remains unavailable without complete goals and verified research data.</p></div></section><section class="panel"><div class="panel-head"><h2>Reports & delivery</h2></div><div class="body-pad"><form id="schedule-form"><div class="form-grid"><label class="field">Preferred day<select name="reportDay">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<option ${d===(p.reportDay||'Saturday')?'selected':''}>${d}</option>`).join('')}</select></label>${field('Local time · Asia/Kolkata','reportTime',p.reportTime||'09:00','time')}</div><div class="form-actions">${btn('Save preference','save-schedule','','primary')}</div></form><p class="tooltip-note">${esc(data.scheduler)}. Saving a preference does not provision a scheduler. Email is disabled until a verified destination and delivery provider are configured.</p></div></section><section class="panel"><div class="panel-head"><h2>Privacy & portability</h2></div><div class="body-pad"><p class="muted">Personal and demo records are stored in separate server-side spaces. Original CSV uploads are discarded after parsing. Exports contain sensitive financial records.</p><div class="form-actions" style="justify-content:flex-start">${btn('Export workspace','export')}${btn('View activity','audit')}</div><div class="divider"></div><h3>Delete ${space==='demo'?'demo changes':'personal records'}</h3><p class="tooltip-note">Erase current workspace records and reports. Demo fixtures reappear after deleting demo changes. Platform sign-in and infrastructure backups are managed separately.</p>${btn('Delete workspace records','delete','','danger')}</div></section><section class="panel"><div class="panel-head"><h2>Workspace</h2></div><div class="body-pad"><div class="stat-row"><span>Current space</span><b>${space==='demo'?'Synthetic demonstration':'Personal'}</b></div><div class="stat-row"><span>Calculation library</span><b>Version 1.0.0</b></div><div class="stat-row"><span>Price convention</span><b>Unadjusted end-of-day price / NAV</b></div><div class="form-actions" style="justify-content:flex-start">${btn(space==='demo'?'Open personal workspace':'Explore demo workspace','switch')}<a class="btn" href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a></div></div></section></div>`;}
function methodology(){return heading('Understand the numbers.','Transparent conventions, explicit assumptions, and room for uncertainty.')+`<section class="panel body-pad methodology"><span class="badge gray">Calculation version 1.0.0</span><h3>Portfolio value & cost basis</h3><p>Position value is units × the latest supplied unadjusted price or published NAV at or before the cutoff. No price is replaced by zero. The portfolio total is partial when positions are unpriced. Remaining known cost uses FIFO lots; opening balances with unknown history have unavailable cost basis and personal XIRR. This app uses an investments-only boundary and does not include a bank cash account.</p><h3>Profit and returns</h3><p>Period investment profit = ending value − starting value − external inflows + external outflows. Purchases and cash fees are outflows from the investor; sales and paid distributions are inflows to the investor. Internal transfers are excluded at consolidated scope. Personal XIRR solves dated investor cash flows using actual days / 365 and r &gt; −1. Non-conventional cash flows are flagged for review; short histories carry an annualization note. Time-weighted returns stay unavailable without valuations around external flows. Published scheme returns are separate from investor returns.</p><h3>SIP scenarios</h3><p>Monthly effective return = (1 + annual effective return)^(1/12) − 1. Month-end payments grow after contribution from the following month; month-beginning payments receive that month’s return. Annual step-ups start after 12 completed contributions. Today’s-cost targets are inflated once. Future-amount targets are not inflated again. Starting SIP is solved under each unchanged scenario. Required SIP is zero when the assigned planning corpus already covers the future target. Returns are illustrative assumptions, not predictions or guarantees; expenses already reflected in NAV must not be deducted twice.</p><h3>Fund evaluation & suitability</h3><p>Active-equity scoring is implemented as a calculation gate: five years of comparable total-return data, at least 95% common daily coverage, complete metrics, and ten underlying schemes are required. Weights: consistency 30%, downside 25%, risk-adjusted return 20%, cost 15%, stability 10%. Passive, ETF, debt and hybrid funds require their own evaluation. No research provider is currently connected, so the UI publishes no fund rankings or candidates. Personal suitability requires risk capacity, goals, liquidity and concentration review. One poor month is not a replacement trigger.</p><h3>Reviewing a change</h3><p>Retain and redirect future contributions should be evaluated before selling. No precise switch benefit is displayed without acquisition lots, effective exit loads, restrictions and verified tax rules. Current tax estimates are unavailable. No orders, redemptions, mandates, or bank debits are executed.</p><h3>Data confidence & reports</h3><p>Every quote carries a valuation date and source. The prototype flags prices older than four calendar days and labels this simplification; verified market calendars remain a provider task. Unknown fund disclosures and classifications stay unknown. Weekly report snapshots are insert-only and keyed by owner, workspace, cutoff and revision. Missing boundary prices produce a partial report with profit unavailable. Manual report generation works without AI or email. Unattended reporting requires a running worker or provisioned scheduler.</p><h3>Source and rule maintenance</h3><p>Scheme categories must be verified by effective date. <a href="https://www.sebi.gov.in/legal/circulars/feb-2026/categorization-and-rationalization-of-mutual-fund-schemes_99983.html" target="_blank" rel="noreferrer">SEBI’s February 2026 categorization circular</a> and <a href="https://www.amfiindia.com/net-asset-value" target="_blank" rel="noreferrer">AMFI’s NAV resources</a> were checked during this build. Public access does not establish a redistribution licence. No permanent tax rates are hardcoded.</p><h3>Privacy and limitations</h3><p>Hosted records require authenticated identity and owner-scoped queries. The demo uses fictitious names and prices. Original CSV text is not stored; parsed rows and audit history remain until deletion. PWA metadata is provided; financial pages and API responses are not cached offline. AI, broker connections, statement PDFs, verified tax calculations, stock fundamentals and email are unavailable until configured and validated. Backup and restore procedures are documented with the source; no restore guarantee is claimed.</p></section>`;}

function showHolding(id){const h=data.portfolio.holdings.find(x=>x.id===id);if(!h)return;const events=data.events.filter(e=>[e.identifier,e.instrument_type,e.plan||'',e.option||''].join('|')===h.key&&e.account===h.account);modal(h.name,`<div class="flex-between"><span class="badge gray">${esc(h.type)} · ${esc(h.plan)} ${esc(h.option)}</span><span class="muted">${esc(h.account)}</span></div><div class="full-grid" style="margin-top:15px"><div><div class="big-stat">${money(h.value)}</div><div class="stat-row"><span>Units</span><b>${number(h.units)}</b></div><div class="stat-row"><span>Known cost basis</span><b>${money(h.basis)}</b></div><div class="stat-row"><span>Unrealized gain</span><b>${money(h.unrealized)}</b></div><div class="stat-row"><span>Realized gain</span><b>${money(h.realized)}</b></div><div class="stat-row"><span>Personal XIRR</span><b>${pct(h.xirr.value)}</b></div><p class="tooltip-note">${esc(h.xirr.reason||'Actual dated investor cash flows · includes final valuation')}</p></div><div><h3>Evidence & review</h3><div class="stat-row"><span>Valuation</span><b>${date(h.quote?.date)}</b></div><div class="stat-row"><span>Source</span><b>${esc(h.quote?.source||'Missing')}</b></div><div class="stat-row"><span>Historical standing</span><b>Insufficient data</b></div><div class="stat-row"><span>Suitability</span><b>Review required</b></div><p class="tooltip-note">${esc(h.issues.join('. ')||'No verified peer or benchmark dataset. No change suggested from available evidence.')}</p><div class="form-actions">${btn('Update price','price',`data-key="${esc(h.key)}"`)}${btn('Compare changes','compare',`data-id="${esc(h.id)}"`)}</div></div></div><div class="divider"></div><h3>Transaction history</h3><div class="table-scroll"><table><thead><tr><th>Date</th><th>Event</th><th class="num">Units</th><th class="num">Amount</th><th>Reference</th></tr></thead><tbody>${events.map(e=>`<tr><td>${date(e.date)}</td><td>${esc(e.type)}</td><td class="num">${number(e.units||0)}</td><td class="num">${money(e.amount)}</td><td>${esc(e.source_reference||'—')}</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:20px">Remaining lots</h3><div class="table-scroll"><table><thead><tr><th>Acquired</th><th>Units</th><th>Known basis</th></tr></thead><tbody>${h.lots.map(l=>`<tr><td>${date(l.date)}</td><td>${number(l.units)}</td><td>${money(l.basis)}</td></tr>`).join('')}</tbody></table></div>`);}
function showCompare(id){const h=data.portfolio.holdings.find(x=>x.id===id);if(!h)return;close();modal('Consider your next move',`<p class="muted">${esc(h.name)} · ${money(h.value)} existing value. No verified return advantage or post-tax benefit has been established.</p><div class="table-scroll"><table><thead><tr><th>Alternative</th><th>Existing units</th><th>Future SIPs</th><th>Costs & uncertainty</th></tr></thead><tbody><tr><td>Retain & continue</td><td>${number(h.units)} retained</td><td>Continue current plan</td><td>No sale proposed</td></tr><tr><td>Retain & redirect</td><td>${number(h.units)} retained</td><td>Change future allocation</td><td>Destination & suitability required</td></tr><tr><td>Staged move</td><td>Selected lots only</td><td>User-defined</td><td>Exit loads, lock-ins & tax unavailable</td></tr><tr><td>Full replacement</td><td>Subject to eligibility</td><td>User-defined</td><td>Exit loads, lock-ins & tax unavailable</td></tr></tbody></table></div><div class="callout amber" style="margin-top:20px">Sale comparison is incomplete. Verified exit-load rules, tax inputs, destination costs and common return assumptions are required before a numerical benefit can be estimated. No action suggested from available evidence.</div><p class="tooltip-note">This screen frames a review. It does not save or execute an investment transaction.</p>`);}
function addInvestment(){modal('Add an investment',`<form id="investment-form"><div class="form-grid">${field('Investment name','name','','text','wide')}${field('Scheme code or ISIN / listing ID','identifier','') }<label class="field">Instrument type<select name="instrument_type"><option value="MF">Mutual fund</option><option value="STOCK">Stock</option><option value="ETF">ETF</option></select></label>${field('Account / folio (masked)','account','My account')}<label class="field">Event<select name="type"><option value="BUY">Purchase</option><option value="OPENING">Opening holding · unknown cost</option><option value="SELL">Sale</option><option value="DIVIDEND">Paid dividend / IDCW</option><option value="SPLIT">Split · enter ratio in price</option><option value="BONUS">Bonus units</option><option value="FEE">Cash fee</option></select></label>${field('Transaction / opening date','date',today(),'date')}${field('Units','units','','number')}${field('Purchase price / split ratio','price','','number')}${field('Gross transaction amount (₹)','amount','','number')}${field('Fees (₹)','fees','0','number')}${field('Unique source reference','source_reference','','text')}<label class="field">MF plan<select name="plan"><option>Direct</option><option>Regular</option></select></label><label class="field">MF option<select name="option"><option>Growth</option><option>IDCW</option></select></label>${field('Category (optional)','category','')}<label class="field">Asset class<select name="asset_class"><option>Unclassified</option><option>Equity</option><option>Debt</option><option>Gold</option><option>Other</option></select></label></div><p class="tooltip-note">Enter the exact instrument identity. Stock IDs should include the exchange. Use a separate dated valuation after posting. Opening holdings carry no invented acquisition date or cost.</p><div class="form-actions">${btn('Cancel','close')}${btn('Preview investment','preview-manual','','primary')}</div></form>`);}
function showPrice(key){if($('#modal').open)close();modal('Record a dated valuation',`<form id="price-form"><div class="form-grid"><label class="field wide">Instrument<select name="instrumentKey">${[...new Map(data.portfolio.holdings.map(h=>[h.key,h])).values()].map(h=>`<option value="${esc(h.key)}" ${h.key===key?'selected':''}>${esc(h.name)} · ${esc(h.plan)} ${esc(h.option)}</option>`).join('')}</select></label>${field('Price / NAV (₹)','price','','number')}${field('Valuation date','date',today(),'date')}${field('Source description','source','Manual valuation','text','wide')}</div><div class="form-actions">${btn('Save valuation','save-price','','primary')}</div></form>`);}
function sipModal(id){const s=data.sips.find(s=>s.id===id)||{name:'',amount:5000,day:5,cadence:'monthly',status:'planned'};modal(id?'Edit SIP schedule':'Plan a steady contribution',`<form id="sip-form"><input type="hidden" name="id" value="${esc(s.id||'')}"><div class="form-grid">${field('Exact investment name','name',s.name,'text','wide')}${field('Contribution (₹)','amount',s.amount,'number')}${field('Planned day (1–28)','day',s.day,'number')}<label class="field">Frequency<select name="cadence"><option value="monthly" ${s.cadence==='monthly'?'selected':''}>Monthly</option><option value="quarterly" ${s.cadence==='quarterly'?'selected':''}>Quarterly · monthly equivalent shown</option></select></label><label class="field">Status<select name="status">${['planned','paused','cancelled'].map(x=>`<option ${x===s.status?'selected':''}>${x}</option>`).join('')}</select></label></div><p class="tooltip-note">This records a contribution plan. It creates no bank mandate. Quarterly plans still require you to verify the intended quarter.</p><div class="form-actions">${btn('Save SIP plan','save-sip','','primary')}</div></form>`);}
function profileModal(){const p=data.preferences.profile||{};modal('Your financial context',`<form id="profile-form"><div class="form-grid">${field('Monthly investable budget (₹)','budget',data.preferences.budget||0,'number','wide')}<label class="field">Emergency reserve<select name="reserve">${['Not assessed','Less than 3 months','3–6 months','More than 6 months'].map(x=>`<option ${p.reserve===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Income stability<select name="income">${['Not assessed','Stable','Variable'].map(x=>`<option ${p.income===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Reaction to a 20% loss<select name="reaction">${['Not assessed','Need to reduce risk','Wait and review','Able to stay invested'].map(x=>`<option ${p.reaction===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Near-term obligations<select name="obligations">${['Not assessed','Material obligations within 3 years','No material obligations within 3 years'].map(x=>`<option ${p.obligations===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('Experience / liquidity needs / debt context','notes',p.notes||'','text','wide')}</div><div class="callout" style="margin-top:20px">Risk willingness and ability to absorb loss are different. These inputs are saved for review; no automated risk profile or aggressive allocation is inferred.</div><div class="form-actions">${btn('Save profile','save-profile','','primary')}</div></form>`);}
function showBatch(batch){preview=batch;if($('#modal').open)close();const counts={};batch.rows.forEach(r=>counts[r.status]=(counts[r.status]||0)+1);modal('Review your import',`<div class="flex-between"><h3>${esc(batch.name)}</h3><span class="badge gray">${esc(batch.status)}</span></div><p class="muted">${Object.entries(counts).map(([k,v])=>v+' '+k).join(' · ')}${batch.accepted?' · '+batch.accepted+' posted':''}</p><div class="table-scroll"><table><thead><tr><th>Row</th><th>Investment</th><th>Event / units</th><th>Status</th><th>Review</th></tr></thead><tbody>${batch.rows.map(r=>`<tr><td>${r.row}</td><td>${esc(r.record.name)}<div class="fund-sub">${esc(r.record.plan)} ${esc(r.record.option)}</div></td><td>${esc(r.record.type)} · ${esc(r.record.units)}</td><td><span class="badge ${r.status==='valid'?'':'amber'}">${r.status}</span></td><td>${r.status==='review'&&batch.status==='previewed'?`<label class="check-label"><input type="checkbox" name="include-row" value="${r.row}"> Separate event</label>`:esc(r.errors.join('; ')||'Ready to post')}</td></tr>`).join('')}</tbody></table></div><p class="tooltip-note">Only valid rows and explicitly approved identical events can post. Duplicate and rejected rows remain outside the ledger. Closing unit differences block the batch. Reversal preserves the audit trail and is rejected if it creates invalid later balances.</p><div class="form-actions">${btn('Close','close')}${batch.status==='previewed'?btn('Confirm & post valid rows','confirm-import','','primary'):batch.status==='posted'?btn('Reverse this batch','reverse-import','','danger'):''}</div>`);}
function showReport(id){const r=data.reports.find(r=>r.id===id);if(!r)return;modal('Your weekly portfolio review',`<div class="report-body"><div class="flex-between"><p class="muted">${date(r.start)} – ${date(r.period)} · Revision ${r.revision}</p><span class="badge ${r.status==='Partial'?'amber':'gray'}">${esc(r.status)}</span></div><div class="full-grid"><div><div class="eyebrow">CLOSING PORTFOLIO VALUE</div><div class="big-stat">${money(r.closing)}</div></div><div><div class="eyebrow">INVESTMENT PROFIT / LOSS</div><div class="big-stat">${money(r.profit)}</div></div></div>${r.reason?`<div class="callout amber">${esc(r.reason)}</div>`:''}<div class="stat-row"><span>Opening portfolio value</span><b>${money(r.opening)}</b></div><div class="stat-row"><span>External inflows</span><b>${money(r.inflows)}</b></div><div class="stat-row"><span>External outflows</span><b>${money(r.outflows)}</b></div><h3>Performance</h3><p>Daily flow-adjusted return and total-return benchmark comparisons are unavailable without matching boundary and benchmark data.</p><h3>SIP activity & goals</h3><p>${r.sips.length} contribution plans and ${r.goals.length} goals captured in this snapshot. Missing imported contributions require review; they do not establish a bank payment failure.</p><h3>Prioritized reviews</h3>${r.actions.length?r.actions.map(a=>`<div class="stat-row"><span>${esc(a.name)}</span><b>${esc(a.reason)}</b></div>`).join(''):'<p>No action suggested from the available evidence.</p>'}<h3>Data confidence</h3><p>${r.dataQuality.stale} stale or unpriced holdings. Unknown disclosures, peer cohorts and tax rules are excluded from conclusions. Sources: ${esc(r.sourceRefs.join('; ')||'None available')}. Calculation version ${r.calculationVersion}.</p><p class="tooltip-note">Frozen ${esc(r.createdAt)}. Later record changes do not rewrite this snapshot.</p></div>`);}
function generateReportModal(){const d=new Date();d.setDate(d.getDate()-((d.getDay()+2)%7||7));modal('Generate a weekly snapshot',`<form id="report-form">${field('Valuation cutoff (completed date)','period',d.toISOString().slice(0,10),'date')}<p class="tooltip-note">The prior seven days are compared using eligible dated prices. Missing or stale boundary values produce a partial report. Repeating the same cutoff returns the same revision.</p><div class="form-actions">${btn('Generate report','save-report','','primary')}</div></form>`);}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const csvColumns=['identifier','name','instrument_type','account','date','type','units','price','amount','fees','currency','source_reference','plan','option','category','valuation_date','closing_units','settlement_date','asset_class'];
function csvEncode(row){return row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',');}
async function handle(action,el){
 if(action==='navigate'){page=el.dataset.page;location.hash=page;$('.sidebar').classList.remove('open');render();}
 if(action==='menu')$('.sidebar').classList.toggle('open');
 if(action==='switch'){space=space==='demo'?'personal':'demo';localStorage.setItem('artha-space',space);preview=null;planner=null;await load();}
 if(action==='close')close();if(action==='period'){period=el.dataset.period;render();}
 if(action==='add-investment')addInvestment();if(action==='holding')showHolding(el.dataset.id);if(action==='compare')showCompare(el.dataset.id);
 if(action==='price')showPrice(el.dataset.key);
 if(action==='save-price'){const b=Object.fromEntries(new FormData($('#price-form')));await request('/prices',b);close();await load();toast('Dated valuation saved');}
 if(action==='new-sip'||action==='edit-sip')sipModal(el.dataset.id);
 if(action==='save-sip'){const b=Object.fromEntries(new FormData($('#sip-form')));if(!b.id)delete b.id;await request('/sips',b);close();await load();toast('Contribution plan saved');}
 if(action==='profile')profileModal();
 if(action==='save-profile'){const b=Object.fromEntries(new FormData($('#profile-form'))),budget=+b.budget;delete b.budget;await request('/preferences',{...data.preferences,budget,profile:{...b,completedAt:new Date().toISOString()}});close();await load();toast('Financial context saved');}
 if(action==='new-goal'){planner=null;page='goals';location.hash='goals';render();$('#planner-form [name=name]').focus();}
 if(action==='edit-goal'){planner=data.goals.find(g=>g.id===el.dataset.id);page='goals';location.hash='goals';render();$('#planner-form').scrollIntoView({behavior:'smooth',block:'center'});}
 if(action==='calculate')await calculatePlanner();
 if(action==='save-goal'){const b=plannerValues();planner=await request('/goals',b);await load();toast('Goal and assumptions saved');}
 if(action==='save-schedule'){const b=Object.fromEntries(new FormData($('#schedule-form')));await request('/preferences',{...data.preferences,...b});await load();toast('Schedule preference saved · scheduler setup still required');}
 if(action==='export'){const response=await fetch('/api/export?space='+space);if(!response.ok)throw new Error('Export failed');download('artha-'+space+'-export.json',await response.text(),'application/json');toast('Private workspace export downloaded');}
 if(action==='template')download('artha-transactions-template.csv',csvColumns.join(',')+'\n'+csvEncode(['SYNTHETIC-INDEX','Sample Index Fund','MF','Folio ••1234','2026-01-05','BUY','10','100','1000','0','INR','sample-ref-001','Direct','Growth','Index fund','2026-01-05','10',''])+'\n','text/csv');
 if(action==='preview-manual'){const b=Object.fromEntries(new FormData($('#investment-form')));if(b.instrument_type!=='MF'){b.plan='';b.option='';}b.currency='INR';const csv=csvColumns.join(',')+'\n'+csvEncode(csvColumns.map(k=>b[k]||''));const batch=await request('/imports',{csv,name:'Manual · '+b.name});showBatch(batch);}
 if(action==='preview-csv'){const mapping=Object.fromEntries(new FormData($('#mapping-form')));const batch=await request('/imports',{csv:csvFile.text,name:csvFile.name,mapping});showBatch(batch);}
 if(action==='batch')showBatch(data.imports.find(x=>x.id===el.dataset.id));
 if(action==='confirm-import'){const include=$$('input[name=include-row]:checked').map(x=>+x.value);await request('/imports/'+preview.id+'/confirm',{include});close();await load();toast('Reviewed transactions posted to the ledger');}
 if(action==='reverse-import'){await request('/imports/'+preview.id+'/reverse',{});close();await load();toast('Batch reversed · audit history preserved');}
 if(action==='generate-report')generateReportModal();
 if(action==='save-report'){const b=Object.fromEntries(new FormData($('#report-form')));const r=await request('/reports',b);close();await load();showReport(r.id);}
 if(action==='read-report')showReport(el.dataset.id);
 if(action==='refresh-nav'){const result=await request('/refresh-nav',{});await load();toast(result.updated+' dated NAVs updated');}
 if(action==='audit'){const rows=await request('/audit');modal('Workspace activity',`<div class="table-scroll"><table><thead><tr><th>Action</th><th>Timestamp (UTC)</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.action)}</td><td>${esc(x.occurred_at)}</td></tr>`).join('')||'<tr><td>No activity yet.</td></tr>'}</tbody></table></div>`);}
 if(action==='delete')modal('Delete workspace records',`<form id="delete-form"><div class="callout amber">This erases all ${space} workspace records, parsed imports, reports and activity. It cannot be undone in the app.</div><div style="margin-top:20px">${field('Type DELETE to confirm','confirm','')}</div><div class="form-actions">${btn('Cancel','close')}${btn('Delete records','confirm-delete','','danger')}</div></form>`);
 if(action==='confirm-delete'){await request('/delete',Object.fromEntries(new FormData($('#delete-form'))));close();await load();toast('Workspace records erased');}
}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(el.disabled)return;el.disabled=true;try{await handle(el.dataset.action,el);}catch(e){toast(e.message,true);}finally{el.disabled=false;}});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('input',e=>{if(['holding-search','holding-type','holding-view'].includes(e.target.id))filterHoldings();if(e.target.closest('#planner-form')){clearTimeout(window.planTimer);window.planTimer=setTimeout(calculatePlanner,400);}});
document.addEventListener('change',async e=>{if(['holding-type','holding-view'].includes(e.target.id))filterHoldings();if(e.target.id==='csv-file'){try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw new Error('CSV must be under 2 MB');csvFile={name:f.name,text:await f.text()};const headers=csvFile.text.replace(/^\uFEFF/,'').split(/\r?\n/)[0].split(',').map(x=>x.trim().replace(/^"|"$/g,''));$('#mapping-area').innerHTML=`<h3 style="margin-top:22px">Map your columns</h3><form id="mapping-form"><div class="mapping-grid">${csvColumns.map(k=>`<label class="field">${k}<select name="${k}"><option value="${k}">Default: ${k}</option>${headers.filter(h=>h!==k).map(h=>`<option value="${esc(h)}">${esc(h)}</option>`).join('')}</select></label>`).join('')}</div>${btn('Validate & preview import','preview-csv','','primary')}</form>`;}catch(err){toast(err.message,true);}}});
function filterHoldings(){let rows=data.portfolio.holdings;const term=$('#holding-search').value.toLowerCase(),type=$('#holding-type').value;rows=rows.filter(h=>(!type||h.type===type)&&(h.name+' '+h.account+' '+h.identifier).toLowerCase().includes(term));if($('#holding-view').value==='consolidated'){const groups=new Map();for(const h of rows){if(!groups.has(h.key))groups.set(h.key,{...h,account:'Consolidated',lots:[...h.lots]});else{const a=groups.get(h.key);a.units=String(Number(a.units)+Number(h.units));a.value=a.value===null||h.value===null?null:String(Number(a.value)+Number(h.value));a.basis=a.basis===null||h.basis===null?null:String(Number(a.basis)+Number(h.basis));a.unrealized=a.basis===null||a.value===null?null:String(Number(a.value)-Number(a.basis));}}rows=[...groups.values()];}$('#holding-rows').innerHTML=holdingsTable(rows);}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(next!==page){page=next;render();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
load();
